 __tablename__="scans"; id:Mapped[str]=uid(); domain_id:Mapped[str]=mapped_column(ForeignKey("domains.id"),index=True); status:Mapped[str]=mapped_column(String(32)); errors:Mapped[str|None]=mapped_column(Text); started_at:Mapped[datetime]=mapped_column(DateTime,default=datetime.utcnow); completed_at:Mapped[datetime|None]=mapped_column(DateTime); domain=relationship("Domain",back_populates="scans")
